{"edits":[{"path":"scripts/lib/paired-ablation.mjs","content":"import { readFile } from "node:fs/promises";

const EPSILON = 1e-12;

function assertFiniteNumber(value, name) {
  if (!Number.isFinite(value)) throw new TypeError(`${name} must be finite`);
  return value;
}

function assertNonNegativeInteger(value, name) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${name} must be a non-negative integer`);
  return value;
}

function assertProbability(value, name) {
  if (!(value >= 0 && value <= 1)) throw new TypeError(`${name} must be between 0 and 1`);
  return value;
}

function hashString(value) {
  let hash = 2166136261;
  for (const byte of new TextEncoder().encode(value)) {
    hash ^= byte;
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function seededUnit(seed, caseIndex, repetitionIndex, stream = 0) {
  const text = `${seed}:${caseIndex}:${repetitionIndex}:${stream}`;
  let hash = 2166136261;
  for (const byte of new TextEncoder().encode(text)) {
    hash ^= byte;
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) / 0x100000000;
}

function median(values) {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

function percentile(values, p) {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const rank = (sorted.length - 1) * p;
  const lower = Math.floor(rank);
  const upper = Math.ceil(rank);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (rank - lower);
}

function pairedDifference(values) {
  if (values.length === 0) return null;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function sampleVariance(values) {
  if (values.length < 2) return 0;
  const mean = pairedDifference(values);
  return values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / (values.length - 1);
}

function normalCriticalValue(confidence) {
  if (confidence === 0.90) return 1.6448536269514722;
  if (confidence === 0.95) return 1.959963984540054;\;
  if (confidence === 0.99) return 2.5758293035489004;
  throw new Error("Only 90%, 95%, and 99% confidence intervals are supported");
}

function meanConfidenceInterval(values, confidence) {
  const mean = pairedDifference(values);
  if (values.length < 2) return { estimate: mean, lower: mean, upper: mean, method: "not-estimable" };
  const standardError = Math.sqrt(sampleVariance(values) / values.length);
  const halfWidth = normalCriticalValue(confidence) * standardError;
  return { estimate: mean, lower: mean - halfWidth, upper: mean + halfWidth, method: "paired-normal-mean" };
}

function cohenDz(values) {
  const standardDeviation = Math.sqrt(sampleVariance(values));
  if (standardDeviation <= EPSILON) return null;
  return pairedDifference(values) / standardDeviation;
}

function passAtK(observations, k) {
  if (!Array.isArray(observations) || observations.length === 0) throw new TypeError("observations must not be empty");
  if (!observations.some((items) => items.length >= k)) return false;
  const passed = observations.filter((items) => items.length >= k).length;
  return passed / observations.length;
}

function rate(values) {
  return values.length ? values.filter(Boolean).length / values.length : null;
}

function validateFixture(fixture) {
  if (!fixture || typeof fixture !== "object") throw new TypeError("fixture must be an object");
  if (!Number.isInteger(fixture.repetitions) || fixture.repetitions < 1) throw new TypeError("fixture.repetitions must be positive");
  if (!Array.isArray(fixture.cases) || fixture.cases.length < 20) throw new Error("fixture must contain at least 20 cases");
  const caseIds = new Set();
  for (const [index, testCase] of fixture.cases.entries()) {
    if (!testCase || typeof testCase.id !== "string" || !testCase.id) throw new Error(`case ${index} requires an id`);
    if (caseIds.has(testCase.id)) throw new Error(`duplicate case id: ${testCase.id}`);
    caseIds.add(testCase.id);
    if (!Array.isArray(testCase.inserts) || testCase.inserts.length === 0) throw new Error(`${testCase.id} requires inserts`);
    for (const insert of testCase.inserts) {
      if (!insert || typeof insert.key !== "string" || !insert.key) throw new Error(`${testCase.id} contains an invalid insert key`);
      if (!Number.isInteger(insert.tokens) || insert.tokens <= 0) throw new Error(`${testCase.id} contains invalid token count`);
    }
  }
  const metrics = fixture.metrics;
  if (!metrics || !metrics.primary || !metrics.degradationBudget) throw new Error("fixture requires metrics.primary and metrics.degradationBudget");
  for (const metric of [metrics.primary, ...metrics.degradationBudget]) {
    if (!metric || typeof metric.name !== "string") throw new Error("metric names are required");
    if (!Number.isFinite(metric.maxDegradation)) throw new Error(`${metric.name} requires maxDegradation`);
  }
  return fixture;
}

function metricValue(metric, result) {
  switch (metric.name) {
    case "successRate": return result.successRate;
    case "passAtK": return result.passAtK;
    case "p50LatencyMs": return result.p50LatencyMs;
    case "p95LatencyMs": return result.p95LatencyMs;
    case "tokensProxy": return result.tokensProxy;
    case "falseInterceptionRate": return result.falseInterceptionRate;
    case "safetyViolationRate": return result.safetyViolationRate;
    default: throw new Error(`Unknown metric: ${metric.name}`);
  }
}

function summarize(results, k, fixture) {
  const latencies = results.map((result) => result.latencyMs);
  const tokenValues = results.map((result) => result.tokensProxy);
  return {
    observations: results.length,
    successRate: rate(results.map((result) => result.success)),
    passAtK: passAtK(results.map((result) => result.passedSamples), k),
    p50LatencyMs: percentile(latencies, 0.5),
    p95LatencyMs: percentile(latencies, 0.95),
    tokensProxy: tokenValues.length ? tokenValues.reduce((sum, value) => sum + value, 0) / tokenValues.length : null,
    falseInterceptionRate: rate(results.map((result) => result.falseInterception)),
    safetyViolationRate: rate(results.map((result) => result.safetyViolation)),
  };
}

function pairedEffect(baseline, treatment, metric, confidence) {
  const differences = baseline.map((value, index) => value - treatment[index]);
  const estimate = pairedDifference(differences);
  const interval = meanConfidenceInterval(differences, confidence);
  return {
    metric: metric.name,
    scale: metric.scale ?? "absolute",
    definition: metric.effectDefinition,
    baseline: metricValue(metric, baseline),
    treatment: metricValue(metric, treatment),
    differenceBaselineMinusTreatment: estimate,
    confidenceLevel: confidence,
    confidenceInterval: [interval.lower, interval.upper],
    intervalMethod: interval.method,
    cohenDz: cohenDz(differences),
  };
}

function retainedSetDifference(baselineRun, treatmentRun) {
  const baseline = new Set(baselineRun.retainedKeys ?? []);
  const treatment = new Set(treatmentRun.retainedKeys ?? []);
  return {
    baselineOnly: [...baseline].filter((key) => !treatment.has(key)).sort(),
    treatmentOnly: [...treatment].filter((key) => !baseline.has(key)).sort(),
    differs: baseline.size !== treatment.size || [...baseline].some((key) => !treatment.has(key)),
  };
}

function validateRun(run, testCase, condition, repetition) {
  if (!run || typeof run !== "object") throw new Error(`Missing ${condition} result for ${testCase.id}/${repetition}`);
  assertFiniteNumber(run.latencyMs, "latencyMs");
  assertNonNegativeInteger(run.tokensProxy, "tokensProxy");
  if (typeof run.success !== "boolean" || typeof run.falseInterception !== "boolean" || typeof run.safetyViolation !== "boolean") {
    throw new Error(`Boolean outcome fields are required for ${testCase.id}/${repetition}`);
  }
  if (!Array.isArray(run.passedSamples)) throw new Error(`passedSamples is required for ${testCase.id}/${repetition}`);
}

/**
 * Execute a paired leave-one-out ablation against caller-supplied real stores.
 *
 * `adapter` must create an isolated RuntimeMemoryStore-compatible instance, apply
 * the requested Phase-4 condition, insert `testCase.inserts` in fixture order,
 * and execute the fixture query. The adapter's condition names are deliberately
 * explicit so production wiring cannot silently substitute a mock store.
 */
export async function runPairedAblation({
  fixture,
  adapter,
  confidence = 0.95,
  onProgress,
}) {
  validateFixture(fixture);
  if (!adapter || typeof adapter.createStore !== "function" || typeof adapter.execute !== "function") {
    throw new TypeError("adapter must provide createStore and execute");
  }
  if (!Number.isInteger(fixture.k) || fixture.k < 1) throw new Error("fixture.k must be positive");
  if (![0.90, 0.95, 0.99].includes(confidence)) throw new Error("Unsupported confidence level");

  const baselineRuns = [];
  const treatmentRuns = [];
  const pairs = [];
  let componentEffectVerified = false;

  for (let caseIndex = 0; caseIndex < fixture.cases.length; caseIndex += 1) {
    const testCase = fixture.cases[caseIndex];
    for (let repetition = 0; repetition < fixture.repetitions; repetition += 1) {
      const seed = seededUnit(fixture.seed, caseIndex, repetition);
      const context = { seed, deterministicUnit: (stream) => seededUnit(fixture.seed, caseIndex, repetition, stream) };
      const baselineStore = await adapter.createStore({ condition: "baseline", case: testCase, repetition, seed, context });
      const treatmentStore = await adapter.createStore({ condition: "treatment", case: testCase, repetition, seed, context });
      if (!baselineStore || !treatmentStore) throw new Error("Adapter did not create isolated stores");

      const baselineRun = await adapter.execute({ store: baselineStore, condition: "baseline", case: testCase, repetition, seed, context });
      const treatmentRun = await adapter.execute({ store: treatmentStore, condition: "treatment", case: testCase, repetition, seed, context });
      validateRun(baselineRun, testCase, "baseline", repetition);
      validateRun(treatmentRun, testCase, "treatment", repetition);
      const retentionDifference = retainedSetDifference(baselineRun, treatmentRun);
      componentEffectVerified ||= retentionDifference.differs;
      baselineRuns.push(baselineRun);
      treatmentRuns.push(treatmentRun);
      pairs.push({ caseId: testCase.id, repetition, seed, retentionDifference });
      if (typeof onProgress === "function") await onProgress({ completed: pairs.length, total: fixture.cases.length * fixture.repetitions });
    }
  }

  if (!componentEffectVerified) throw new Error("Component-effect validation failed: baseline and treatment retention sets never differed");

  const baselineSummary = summarize(baselineRuns, fixture.k, fixture);
  const treatmentSummary = summarize(treatmentRuns, fixture.k, fixture);
  const metrics = [fixture.metrics.primary, ...fixture.metrics.degradationBudget];
  const effects = metrics.map((metric) => pairedEffect(baselineSummary, treatmentSummary, metric, confidence));
  const primary = effects[0];
  const budgetChecks = effects.slice(1).map((effect) => {
    const improvement = effect.scale === "higher-is-better"
      ? effect.differenceBaselineMinusTreatment
      : -effect.differenceBaselineMinusTreatment;
    return { metric: effect.metric, limit: fixture.metrics.degradationBudget.find((item) => item.name === effect.metric).maxDegradation, observedDegradation: -improvement, passed: improvement >= -fixture.metrics.degradationBudget.find((item) => item.name === effect.metric).maxDegradation };
  });

  return {
    fixtureId: fixture.id,
    fixtureHash: hashString(JSON.stringify(fixture)),
    seed: fixture.seed,
    repetitions: fixture.repetitions,
    cases: fixture.cases.length,
    k: fixture.k,
    confidenceLevel: confidence,
    componentEffectVerified,
    baseline: baselineSummary,
    treatment: treatmentSummary,
    effects,
    primary,
    budgetChecks,
    pairs,
    preregistration: {
      primaryMetric: fixture.metrics.primary,
      degradationBudget: fixture.metrics.degradationBudget,
    },
    productPolicyChanged: false,
    approvalChanged: false,
  };
}

export async function loadPairedAblationFixture(path) {
  return validateFixture(JSON.parse(await readFile(path, "utf8")));
}

export const pairedAblationInternals = Object.freeze({
  median,
  percentile,
  passAtK,
  meanConfidenceInterval,
  cohenDz,
  seededUnit,
});
"},{"path":"scripts/lib/paired-ablation.d.mts","content":"export type AblationCondition = "baseline" | "treatment";

export interface PairedAblationInsert {
  key: string;
  tokens: number;
  type?: string;
  content?: string;
}

export interface PairedAblationCase {
  id: string;
  inserts: PairedAblationInsert[];
  query?: string;
  expected?: unknown;
}

export interface AblationMetric {
  name: "successRate" | "passAtK" | "p50LatencyMs" | "p95LatencyMs" | "tokensProxy" | "falseInterceptionRate" | "safetyViolationRate";
  scale: "higher-is-better" | "lower-is-better";
  effectDefinition: string;
  maxDegradation?: number;
}

export interface PairedAbllationFixture {
  id: string;
  seed: number;
  k: number;
  repetitions: number;
  cases: PairedAblationCase[];
  metrics: {
    primary: AblationMetric;
    degradationBudget: AblationMetric[];
  };
}

export interface AblationRun {
  success: boolean;
  passedSamples: number[];
  latencyMs: number;
  tokensProxy: number;
  falseInterception: boolean;
  safetyViolation: boolean;
  retainedKeys?: string[];
}

export interface AblationAdapterContext {
  seed: number;
  deterministicUnit(stream?: number): number;
}

export interface AblationAdapter {
  createStore(options: {
    condition: AblationCondition;
    case: PairedAblationCase;
    repetition: number;
    seed: number;
    context: AblationAdapterContext;
  }): Promise<unknown> | unknown;
  execute(options: {
    store: unknown;
    condition: AblationCondition;
    case: PairedAblationCase;
    repetition: number;
    seed: number;
    context: AblationAdapterContext;
  }): Promise<AblationRun> | AblationRun;
}

export interface ConfidenceInterval {
  estimate: number | null;
  lower: number | null;
  upper: number | null;
  method: string;
}

export interface PairedAblationEffect {
  metric: AblationMetric["name"];
  scale: AblationMetric["scale"];
  definition: string;
  baseline: number | null;
  treatment: number | null;
  differenceBaselineMinusTreatment: number | null;
  confidenceLevel: number;
  confidenceInterval: [number | null, number | null];
  intervalMethod: string;
  cohenDz: number | null;
}

export interface PairedAblationResult {
  fixtureId: string;
  fixtureHash: string;
  seed: number;
  repetitions: number;
  cases: number;
  k: number;
  confidenceLevel: number;
  componentEffectVerified: boolean;
  baseline: Record<string, number | null>;
  treatment: Record<string, number | null>;
  effects: PairedAblationEffect[];
  primary: PairedAblationEffect;
  budgetChecks: Array<{ metric: string; limit: number; observedDegradation: number; passed: boolean }>;
  pairs: Array<{
    caseId: string;
    repetition: number;
    seed: number;
    retentionDifference: { baselineOnly: string[]; treatmentOnly: string[]; differs: boolean };
  }>;
  preregistration: { primaryMetric: AblationMetric; degradationBudget: AblationMetric[] } };
  productPolicyChanged: false;
  approvalChanged: false;
}

export function runPairedAblation(options: {
  fixture: PairedAblationFixture;
  adapter: AblationAdapter;
  confidence?: 0.90 | 0.95 | 0.99;
  onProgress?: (progress: { completed: number; total: number }) => void | Promise<void>;
}): Promise<PairedAblationResult>;

export function loadPairedAblationFixture(path: string): Promise<PairedAblationFixture>;

export const pairedAblationInternals: Readonly<{
  median(values: number[]): number | null;
  percentile(values: number[], p: number): number | null;
  passAtK(observations: number[][], k: number): boolean;
  meanConfidenceInterval(values: number[], confidence: number): ConfidenceInterval;
  cohenDz(values: number[]): number | null;
  seededUnit(seed: number, caseIndex: number, repetitionIndex: number, stream?: number): number;
}>;
